// Add to sw.js after the install handler.
self.addEventListener("fetch", event => {
  if (event.request.mode === "navigate") {
    event.respondWith(fetch(event.request).catch(async () => {
      return await caches.match("/offline.html") || new Response("You are offline.", {headers:{"Content-Type":"text/plain"}});
    }));
  }
});

// Example helper inside sw.js
async function cachedAsset(request) {
  const cache = await caches.open("reading-assets-v1");
  const saved = await cache.match(request);
  if (saved) return saved;
  const response = await fetch(request);
  if (response.ok) await cache.put(request, response.clone());
  return response;
}

self.addEventListener("activate", event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(
    keys.filter(key => key.startsWith("reading-") && !["reading-v1", "reading-assets-v1"].includes(key)).map(key => caches.delete(key))
  )));
});

navigator.serviceWorker.ready.then(registration => {
  console.log("Active worker:", registration.active?.scriptURL);
  console.log("Waiting worker:", registration.waiting?.scriptURL);
});

try {
